-- Generated by scripts/gen_catalog.py — do not edit by hand
-- Feasibility-study catalog: sectors, studies, purchase requests.
-- Prices are intentionally NULL (shown as 'السعر عند التواصل') until set by an admin.
CREATE TABLE IF NOT EXISTS catalog_sectors (
  id TEXT PRIMARY KEY,
  name_ar TEXT NOT NULL,
  tagline TEXT,
  description TEXT,
  icon TEXT,
  image TEXT,
  color TEXT,
  items_json TEXT NOT NULL DEFAULT '[]',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS catalog_studies (
  id TEXT PRIMARY KEY,
  sector_id TEXT NOT NULL REFERENCES catalog_sectors(id),
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  icon TEXT,
  image TEXT,
  summary TEXT,
  description TEXT,
  contents_json TEXT NOT NULL DEFAULT '[]',
  requirements_json TEXT NOT NULL DEFAULT '[]',
  cost_items_json TEXT NOT NULL DEFAULT '[]',
  revenue_json TEXT NOT NULL DEFAULT '[]',
  risks_json TEXT NOT NULL DEFAULT '[]',
  deliverables TEXT,
  price REAL,
  currency TEXT NOT NULL DEFAULT 'EGP',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_catalog_studies_sector ON catalog_studies(sector_id, is_active, sort_order);
CREATE TABLE IF NOT EXISTS purchase_requests (
  id TEXT PRIMARY KEY,
  study_id TEXT REFERENCES catalog_studies(id),
  study_title TEXT NOT NULL,
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  email TEXT,
  governorate TEXT,
  budget TEXT,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','contacted','completed','cancelled')),
  ip_hash TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_purchase_requests_status ON purchase_requests(status, created_at);
