INSERT OR IGNORE INTO catalog_sectors (id,name_ar,tagline,description,icon,image,color,items_json,sort_order) VALUES ('agriculture','قطاع الثروة الزراعية','مشروعات زراعية مستدامة من الحقل حتى التعبئة والتصدير','دراسات جدوى لمشروعات الإنتاج الزراعي والصوب والمشاتل وما بعد الحصاد، تراعي توافر المياه والتربة والمناخ وسلاسل التوريد ومتطلبات الجودة.','fa-seedling','/static/img/sectors/agri.jpg','#15803d','["زراعة الخضروات والفاكهة", "الصوب الزراعية", "النباتات الطبية والعطرية", "المشاتل", "زراعة التمور", "تجفيف وتعبئة المحاصيل"]',1);
INSERT OR IGNORE INTO catalog_studies (id,sector_id,slug,title,icon,image,summary,description,contents_json,requirements_json,cost_items_json,revenue_json,risks_json,deliverables,price,sort_order) VALUES ('cs-vegetables-fruits','agriculture','vegetables-fruits','دراسة جدوى زراعة الخضروات والفاكهة','fa-carrot','/static/img/sectors/agri.jpg','دراسة لمشروع زراعة محاصيل خضر وفاكهة مختارة حسب الموسم والمنطقة، مع تخطيط الدورة الزراعية وتقدير الإنتاجية وقنوات التسويق.','دراسة لمشروع زراعة محاصيل خضر وفاكهة مختارة حسب الموسم والمنطقة، مع تخطيط الدورة الزراعية وتقدير الإنتاجية وقنوات التسويق. دراسات جدوى لمشروعات الإنتاج الزراعي والصوب والمشاتل وما بعد الحصاد، تراعي توافر المياه والتربة والمناخ وسلاسل التوريد ومتطلبات الجودة. الدراسة مبنية على افتراضات واضحة قابلة للمراجعة، ولا تمثل ضمانًا لتحقيق أرباح؛ ويُنصح بمراجعة الأرقام مع مختص قبل اتخاذ قرار الاستثمار.','["الملخص التنفيذي وفكرة المشروع", "الدراسة السوقية وتحليل الطلب والمنافسين", "الدراسة الفنية: الموقع، المساحة، المعدات وخطوط التشغيل", "الهيكل الإداري والعمالة المطلوبة", "التراخيص والاشتراطات القانونية والتنظيمية", "التكاليف الاستثمارية (أصول ثابتة ومصروفات ما قبل التشغيل)", "التكاليف التشغيلية الثابتة والمتغيرة", "تقديرات الإيرادات وخطة المبيعات", "القوائم المالية المتوقعة (الدخل، التدفقات النقدية، الميزانية)", "المؤشرات المالية: صافي القيمة الحالية، معدل العائد الداخلي، فترة الاسترداد، نقطة التعادل", "تحليل السيناريوهات والحساسية", "تحليل المخاطر وخطة التخفيف", "خطة التنفيذ والجدول الزمني", "التوصيات والافتراضات والمصادر"]','["توافر مصدر مياه مناسب وتحليل للتربة", "ملكية أو عقد إيجار للأرض", "تراخيص وزارة الزراعة والجهات المحلية المختصة", "خطة تسويق وقنوات بيع أو تعاقدات مسبقة"]','["الأرض أو إيجارها واستصلاحها", "شبكات الري والآبار", "البذور والشتلات والأسمدة والمبيدات", "العمالة الموسمية والدائمة", "النقل والتعبئة والتخزين"]','["بيع المحصول للتجار وأسواق الجملة", "التعاقد مع المصانع والمصدرين", "البيع المباشر للمستهلك والمنافذ"]','["تقلبات المناخ والآفات", "تذبذب أسعار البيع موسميًا", "ارتفاع تكلفة المدخلات", "محدودية المياه"]','ملف PDF منسق + ملف Excel للقوائم المالية قابل للتعديل. يتم تحديث الأرقام وفق موقعك وحجم مشروعك عند التواصل.',NULL,1);
